const fs = require('fs');

const digits = fs.readFileSync(0, 'utf8').trim().split('').map(Number);
const memo = new Map();

function dp(pos, mask, tight) {
    if (pos === digits.length) return mask !== 0 ? 1 : 0;

    const key = `${pos},${mask},${tight}`;
    if (memo.has(key)) return memo.get(key);

    const limit = tight ? digits[pos] : 9;
    let count = 0;

    for (let digit = 0; digit <= limit; digit++) {
        let nextMask = mask;

        if (mask === 0 && digit === 0) {
            nextMask = 0;
        } else {
            nextMask |= 1 << digit;
            if ((nextMask & (nextMask - 1)) !== 0) {
                const withoutOneBit = nextMask & (nextMask - 1);
                if ((withoutOneBit & (withoutOneBit - 1)) !== 0) continue;
            }
        }

        count += dp(pos + 1, nextMask, tight && digit === limit);
    }

    memo.set(key, count);
    return count;
}

console.log(dp(0, 0, true));

