const memo = new Map();

function dfs(pos, tight, started, mask) {
    if (pos === digits.length) return started ? 1 : 0;

    const key = `${pos},${started ? 1 : 0},${mask}`;
    if (!tight && memo.has(key)) return memo.get(key);

    const limit = tight ? digits[pos] : 9;
    let count = 0;

    for (let d = 0; d <= limit; d++) {
        const nextTight = tight && d === limit;

        if (!started && d === 0) {
            count += dfs(pos + 1, nextTight, false, 0);
        } else {
            const nextMask = mask | (1 << d);
            if ((nextMask & (nextMask - 1)) === 0 ||
                ((nextMask & (nextMask - 1)) & ((nextMask & (nextMask - 1)) - 1)) === 0) {
                count += dfs(pos + 1, nextTight, true, nextMask);
            }
        }
    }

    if (!tight) memo.set(key, count);
    return count;
}

